def adaptiveMode (B S η residual previousMinimum w : ℝ) (M t c : ℕ) : Mode :=
  if w≤threshold B S (t+1) then .ab S (t+1) 0
  else if residual<η*previousMinimum ∧ c<M then .ab S (t+1) (c+1)
  else .bisection

def decisionWord (g : Word) : Nat :=
  if Model.compare g guardWord = some .gt then 3
  else if Model.compare g (Model.neg guardWord) = some .lt then 2 else 1

def leftStep (p : ℕ) (s : LeftState) : LeftState :=
  let t:=leftTrial p s.e s.v
  ⟨t,if s.correct then s.v*(1-t^p/s.e^p) else s.v,true⟩

def Domain (env : Nat → ℝ) : Prop :=
  env 0 ≠ 0 ∧ env 1 ≠ 0 ∧
  ((env 0 ≤ 0 ∧ 0 ≤ env 1) ∨ (env 1 ≤ 0 ∧ 0 ≤ env 0))

def evaluate (f1 f2 f3 : ℝ) : Values :=
  let su := Binary64.round (f1+f2)
  let di := Binary64.round (f2-f1)
  let y := Binary64.round (su/2)
  let v := Binary64.round (|y|/|di|)
  let r := Binary64.round (1-v)
  let k := Binary64.round (r*r)
  let leftDiff := Binary64.round (f3-y)
  let py := Binary64.round (k*|y|)
  let pz := Binary64.round (k*|f3|)
  ⟨su,di,y,v,r,k,leftDiff,py,pz,Binary64.round (py+pz)⟩

def topLeftSeed (a v : ℝ) : LeftState :=
  let s := ModAB.Convergence.recordUpdate ⟨a,v,a,v,none⟩ .left (-1)
  ⟨1,s.rightWork,decide (s.previous = some .left)⟩
